#pragma once

#include <cstddef>

// A file packed into the app at build time
struct EmbeddedFile
{
	const char* name;
	const unsigned char* data;
	size_t size;
};

// Every embedded file, listed in CMakeLists.txt and generated by cmake/EmbedFiles.cmake
extern const EmbeddedFile EMBEDDED_FILES[];
extern const int EMBEDDED_FILE_COUNT;
